# -*- coding: utf-8 -*-
# patch_mt5_feed.py
# ============================================================
# ПАТЧ: насос котировок MT5 без привязки к активу/таймфрейму.
# Спринт 45 · 2026-06-16
#
# Что делает:
#   1. main.py            — вырезан встроенный MT5-мост, вставлен запуск насоса
#   2. williams_core.py   — POINT_MAP убран, point обязателен (v1.1)
#   3. hooks.py           — мозги агентов переехали сюда из main.py
#   4. mt5_feed.py        — НОВЫЙ модуль-насос
#   5. state/feed_config.json — НОВЫЙ конфиг наблюдения
#
# Перед заменой делает .bak каждого существующего файла.
# Запуск из корня репо:  python patch_mt5_feed.py
# ============================================================
import base64, os, shutil, sys

FILES = {
    "main.py": "",
    "studio/modules/trading/williams_core.py": "",
    "studio/modules/trading/hooks.py": "",
    "studio/modules/trading/mt5_feed.py": "",
    "studio/modules/trading/state/feed_config.json": ""
}

def main():
    root = os.getcwd()
    print("=" * 60)
    print("  ПАТЧ MT5 FEED — насос котировок")
    print("  Корень:", root)
    print("=" * 60)

    for dest, b64 in FILES.items():
        path = os.path.join(root, dest.replace("/", os.sep))
        os.makedirs(os.path.dirname(path), exist_ok=True)

        if os.path.exists(path):
            bak = path + ".bak"
            shutil.copy2(path, bak)
            print(f"  [BAK] {dest}  ->  {dest}.bak")

        data = base64.b64decode(b64)
        with open(path, "wb") as f:
            f.write(data)
        print(f"  [OK ] {dest}  ({len(data)} bytes)")

    print("=" * 60)
    print("  ГОТОВО. Файлы заменены, бэкапы рядом (.bak).")
    print("")
    print("  Дальше:")
    print("   1. Открой терминал MetaTrader 5, подключись к ДЕМО-счёту")
    print("   2. Включи 'Разрешить автоматическую торговлю' в терминале")
    print("   3. Запусти студию как обычно — насос поднимется в фоне")
    print("   4. Смотри лог: [FEED] ... — насос качает котировки")
    print("")
    print("  Боевой режим (реальные ордера) ВЫКЛЮЧЕН. Включается")
    print("  только флагом live:true в state/feed_config.json.")
    print("=" * 60)

if __name__ == "__main__":
    main()
